/* @lc app=leetcode id=3589 lang=kotlin */ class Solution { fun primeSubarray(nums: IntArray, k: Int): Int = (0..50000).map { x -> x >= 2 && (2..Math.sqrt(x.toDouble()).toInt()).none { x % it == 0 } }.let { pr -> java.util.ArrayDeque<Int>().let { mx -> java.util.ArrayDeque<Int>().let { mn -> ArrayList<Int>().let { ps -> nums.indices.fold(0 to 0L) { (l, ans), r -> (if (pr[nums[r]]) generateSequence { mx.peekLast()?.takeIf { nums[it] <= nums[r] } }.forEach { _ -> mx.pollLast() }.let { mx.addLast(r) }.let { generateSequence { mn.peekLast()?.takeIf { nums[it] >= nums[r] } }.forEach { _ -> mn.pollLast() } }.let { mn.addLast(r) }.let { ps.add(r) } else Unit).let { generateSequence(l) { ll -> if (mx.isNotEmpty() && nums[mx.peekFirst()] - nums[mn.peekFirst()] > k) (ll + 1).also { nl -> (if (mx.peekFirst() < nl) mx.pollFirst() else null).let { if (mn.peekFirst() < nl) mn.pollFirst() } } else null }.last() }.let { l2 -> l2 to ans + (if (ps.size >= 2 && l2 <= ps[ps.size - 2]) ps[ps.size - 2] - l2 + 1 else 0) } }.second.toInt() } } } } }